    return str(min(max(w, 1), 2))


def loads(s: Any, default=None):
    if s is None or (isinstance(s, float) and pd.isna(s)) or s == "":
        return default
    if isinstance(s, (dict, list)):
        return s
    try:
        return json.loads(s)
    except (TypeError, ValueError):
        return default


